import {Simulation,TYPES} from './engine.js';
import {Renderer,SYMBOLS} from './renderer.js';
import {Soundscape} from './audio.js';
const $=id=>document.getElementById(id);
const renderer=new Renderer($('map')),audio=new Soundscape();
let sim,speed=1,selectedId=null,deployType=null,strikeArmed=false,toastTimer,last=performance.now(),uiClock=0,resultShown=false,activeModal=null,resumeAfterModal=false,eventCount=-1,contactSignature='',settings={volume:40,voice:true,reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,difficulty:'standard'};
try{const s=JSON.parse(localStorage.getItem('blackout-settings'));if(s&&typeof s==='object')settings={...settings,...s};}catch{}
audio.volume=Math.max(0,Math.min(1,Number(settings.volume)/100||0));audio.voice=!!settings.voice;renderer.reduced=!!settings.reduced;
$('volume').value=settings.volume;$('volume-value').textContent=`${settings.volume}%`;$('voice').checked=settings.voice;$('reduced').checked=settings.reduced;$('difficulty').value=settings.difficulty;
const phaseNames={5:'PEACETIME',4:'HEIGHTENED ALERT',3:'WEAPONS FREE',2:'STRATEGIC ALERT',1:'NUCLEAR WAR'};
const phaseCopy={5:'Deploy your forces.<br>All weapons on hold.',4:'Final deployment window.<br>Hostilities imminent.',3:'Conventional weapons free.<br>Deployment is closed.',2:'Strategic forces on alert.<br>Nuclear weapons locked.',1:'Nuclear release authorized.<br>Protect your cities.'};
const formatTime=t=>{t=Math.floor(t);return `${String(Math.floor(t/3600)).padStart(2,'0')}:${String(Math.floor(t/60)%60).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;};
const coordinate=(v,pos,neg)=>`${Math.abs(v).toFixed(2)}° ${v>=0?pos:neg}`;
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4200);}
function selected(){return sim.units.find(u=>u.id===selectedId);}
function selectUnit(u){selectedId=u?.id??null;renderer.selected=selectedId;deployType=null;strikeArmed=false;document.querySelectorAll('.deploy-button').forEach(b=>b.classList.remove('active'));renderInspector();updateUI();}
function configureSimulation(options={}){sim=new Simulation({difficulty:settings.difficulty,seed:Date.now()>>>0,...options});sim.onEffect=(type)=>{audio.effect(type,sim.phase);if(type==='nuclear'&&!renderer.reduced){document.body.classList.remove('nuclear-flash');void document.body.offsetWidth;document.body.classList.add('nuclear-flash');setTimeout(()=>document.body.classList.remove('nuclear-flash'),1800);}};sim.onEvent=e=>{if(e.kind==='alert'&&e.message.startsWith('DEFCON'))showAlert();};selectedId=null;renderer.selected=null;deployType=null;strikeArmed=false;resultShown=false;eventCount=-1;contactSignature='';renderer.reset(sim.mode==='lab');if(options.left==='nuclear'||options.right==='nuclear'){renderer.zoom=1.8;renderer.pan.y=14*renderer.scale;}$('war-tab').classList.toggle('active',sim.mode==='war');$('lab-tab').classList.toggle('active',sim.mode==='lab');$('theater-label').textContent=sim.mode==='lab'?'CONTROLLED ENGAGEMENT ZONE':'NORTH ATLANTIC THEATER';$('map-subtitle').textContent=sim.mode==='lab'?`${(options.left||'battleship').toUpperCase()} VS ${(options.right||'bomber').toUpperCase()} / LIVE TELEMETRY`:'OPERATION BLACKOUT / DAY 001';$('result-dialog').close();$('escalation-alert').hidden=true;document.querySelectorAll('.deploy-button').forEach(b=>b.classList.remove('active'));updateUI();}
function begin(){if(sim.ended){configureSimulation();}sim.running=true;$('begin').textContent=sim.mode==='lab'?'ENGAGEMENT LIVE':'OPERATION LIVE';$('begin').disabled=true;$('pause').disabled=false;audio.speak(sim.mode==='lab'?'Battle laboratory active. Weapons free.':'Command uplink established. Defense condition five. Awaiting your orders.');updateUI();}
function togglePause(){if(sim.ended)return;if($('begin').disabled===false){begin();return;}sim.running=!sim.running;updateUI();}
function setSpeed(s){speed=s;document.querySelectorAll('[data-speed]').forEach(b=>b.classList.toggle('active',+b.dataset.speed===s));}
function showAlert(){const e=$('escalation-alert');e.querySelector('b').textContent=sim.phase;e.querySelector('p').textContent=phaseNames[sim.phase];e.hidden=false;clearTimeout(showAlert.timer);showAlert.timer=setTimeout(()=>e.hidden=true,3300);}
function openDialog(id){if(activeModal)return;activeModal=id;resumeAfterModal=sim.running;sim.running=false;$(id).showModal();updateUI();}
for(const id of ['manual-dialog','settings-dialog','lab-dialog'])$(id).addEventListener('close',()=>{if(activeModal===id){activeModal=null;if(resumeAfterModal&&!sim.ended)sim.running=true;resumeAfterModal=false;updateUI();}});
function closeDialog(id){$(id).close();}
$('help').onclick=()=>openDialog('manual-dialog');$('manual-ready').onclick=()=>closeDialog('manual-dialog');$('settings').onclick=()=>openDialog('settings-dialog');$('save-settings').onclick=()=>{settings={volume:+$('volume').value,voice:$('voice').checked,reduced:$('reduced').checked,difficulty:$('difficulty').value};audio.setVolume(settings.volume/100);audio.voice=settings.voice;renderer.reduced=settings.reduced;try{localStorage.setItem('blackout-settings',JSON.stringify(settings));}catch{}closeDialog('settings-dialog');toast('Terminal settings saved.');};$('volume').oninput=()=>{$('volume-value').textContent=`${$('volume').value}%`;audio.setVolume(+$('volume').value/100);};
$('sound').onclick=async()=>{const enabled=await audio.toggle();$('sound').innerHTML=`♫ <span>AUDIO ${enabled?'ON':'OFF'}</span>`;$('sound').setAttribute('aria-label',enabled?'Mute sound':'Enable sound');$('sound').setAttribute('aria-pressed',String(enabled));if(enabled){toast('Audio online. Headphones recommended.');audio.speak('Secure audio link established.');}else toast('Audio muted.');};
$('begin').onclick=begin;$('pause').onclick=togglePause;document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>setSpeed(+b.dataset.speed));
$('escalate').onclick=()=>{if(sim.mode==='lab'){toast('Battle lab already has all weapons authorized.');return;}sim.escalate();updateUI();};
$('war-tab').onclick=()=>{if(sim.mode==='war')return;configureSimulation();toast('New global operation ready. Deploy forces and begin.');};$('lab-tab').onclick=()=>{updateLabWarning();openDialog('lab-dialog');};
$('new-game').onclick=()=>{if(sim.running){sim.running=false;toast('Simulation paused. Click NEW OPERATION again to restart.');updateUI();return;}configureSimulation();toast('Fresh operation initialized.');};$('restart').onclick=()=>{configureSimulation();};$('review-map').onclick=()=>{$('result-dialog').close();};
$('zoom-in').onclick=()=>renderer.changeZoom(1.3);$('zoom-out').onclick=()=>renderer.changeZoom(1/1.3);$('reset-view').onclick=()=>renderer.reset(sim.mode==='lab');$('layers').onclick=()=>{renderer.coverage=!renderer.coverage;$('layers').setAttribute('aria-pressed',String(renderer.coverage));toast(renderer.coverage?'Radar and air-defense coverage visible.':'Radar coverage hidden.');};
const deployments=['battleship','carrier','submarine','fighter','bomber','silo','radar'];
$('deployment-list').innerHTML=deployments.map(type=>{const t=TYPES[type];return `<button class="deploy-button" data-type="${type}"><span class="unit-symbol">${SYMBOLS[type]}</span><span class="deploy-name">${t.name}<small>${t.domain==='sea'?'NAVAL':t.domain==='air'?'AVIATION':'STRATEGIC'} / ${t.hp} HP</small></span><span class="deploy-cost">${t.cost} CR</span></button>`;}).join('');
$('deployment-list').onclick=e=>{const b=e.target.closest('[data-type]');if(!b)return;selectUnit(null);deployType=b.dataset.type;b.classList.add('active');toast(`${TYPES[deployType].name} selected. Click inside the western sector to deploy.`);updateUI();};
function renderInspector(){const u=selected();$('unit-count').textContent=u?`CONTACT ${u.id}`:'NO CONTACT';if(!u){$('inspector').innerHTML='<div class="inspector-empty"><span>⌖</span><h3>Awaiting selection</h3><p>Select any unit on the map<br>to inspect its status.</p></div>';return;}const t=TYPES[u.type],friendly=u.team===0;const canNuke=['silo','bomber','submarine'].includes(u.type);$('inspector').innerHTML=`<div class="selected-title"><span class="unit-symbol" style="color:${friendly?'var(--blue)':'var(--red)'}">${SYMBOLS[u.type]}</span><div><h3>${t.name}</h3><small>${friendly?'ALLIED':'HOSTILE'} / ${u.dead?'DESTROYED':u.order?'UNDERWAY':'HOLDING POSITION'}</small></div></div><div class="phase-timer"><span>HULL INTEGRITY</span><span>${Math.ceil(u.hp)} / ${u.maxHp}</span></div><div class="hp-bar"><i style="width:${u.hp/u.maxHp*100}%"></i></div><div class="unit-stats"><span>WEAPON RANGE<strong>${t.range}°</strong></span><span>CONFIRMED KILLS<strong>${u.kills}</strong></span><span>COOLDOWN<strong>${u.cooldown.toFixed(1)}s</strong></span><span>${canNuke?'WARHEADS':'DAMAGE / SHOT'}<strong>${canNuke?u.ammo:t.damage}</strong></span></div>${canNuke&&friendly&&!u.dead?`<button id="arm-strike" class="strike-button ${strikeArmed?'armed':''}" ${sim.phase!==1||u.ammo<=0?'disabled':''}>${sim.phase!==1?'☢ LOCKED UNTIL DEFCON 1':strikeArmed?'☢ SELECT STRIKE TARGET':'☢ ARM NUCLEAR STRIKE'}</button>`:''}<p class="inspector-help">${u.dead?'Contact lost. Unit destroyed.':strikeArmed?'Click the map to launch. Escape cancels.':friendly&&t.speed?'Click a destination or hostile contact on the map to issue orders.':friendly?'Stationary installation. Automatic air defense.':'Hostile contact. Select a friendly unit to engage.'}</p>`;const arm=$('arm-strike');if(arm)arm.onclick=()=>{strikeArmed=!strikeArmed;renderInspector();updateUI();};}
function renderContacts(){const live=sim.units.filter(u=>!u.dead&&u.team===0);const signature=live.map(u=>`${u.id}:${Math.ceil(u.hp/10)}:${!!u.order}`).join(',')+'s'+selectedId;if(signature===contactSignature)return;contactSignature=signature;$('contacts').innerHTML=live.map(u=>`<button class="contact ${selectedId===u.id?'active':''}" data-contact="${u.id}"><span class="unit-symbol">${SYMBOLS[u.type]}</span><span>${TYPES[u.type].name} <small>${String(u.id).padStart(3,'0')} / ${u.order?'UNDERWAY':'STANDBY'}</small></span><span class="health">${Math.ceil(u.hp/u.maxHp*100)}%</span></button>`).join('');$('contact-count').textContent=live.length;}
$('contacts').onclick=e=>{const b=e.target.closest('[data-contact]');if(!b)return;const u=sim.units.find(u=>u.id===+b.dataset.contact);selectUnit(u);const p=renderer.project(u.x,u.y);renderer.pan.x+=renderer.width/2-p.x;renderer.pan.y+=renderer.height/2-p.y;};
function updateUI(){
 $('clock').textContent=formatTime(sim.time);$('defcon-number').textContent=sim.phase;$('defcon-name').textContent=phaseNames[sim.phase];$('phase-description').innerHTML=phaseCopy[sim.phase];$('phase-status').textContent=sim.ended?'CEASEFIRE':sim.running?'ACTIVE':'STANDBY';$('pause').textContent=sim.running?'Ⅱ':'▶';$('pause').setAttribute('aria-label',sim.running?'Pause simulation':'Resume simulation');
 if(!$('begin').disabled||sim.time===0&&!sim.running){$('begin').disabled=false;$('begin').textContent=sim.mode==='lab'?'BEGIN ENGAGEMENT ↗':'BEGIN OPERATION ↗';$('pause').disabled=true;}
 if(sim.running){$('begin').disabled=true;$('pause').disabled=false;}
 if(sim.ended){$('begin').textContent='OPERATION ENDED';$('begin').disabled=true;$('pause').disabled=true;}
 document.querySelectorAll('[data-phase]').forEach(e=>e.classList.toggle('active',+e.dataset.phase===sim.phase));document.body.classList.toggle('high-alert',sim.phase<=2);
 const next=Math.max(0,(6-sim.phase)*55-sim.time);$('next-phase').textContent=sim.phase===1?'RELEASED':`${String(Math.floor(next/60)).padStart(2,'0')}:${String(Math.floor(next%60)).padStart(2,'0')}`;$('phase-progress').style.width=sim.phase===1?'100%':`${Math.max(0,Math.min(100,100-next/55*100))}%`;
 $('credits').textContent=`${sim.budget} CR`;$('alive-count').textContent=sim.units.filter(u=>!u.dead&&u.team===0).length;$('nuke-count').textContent=sim.remaining[0];$('kill-count').textContent=sim.kills[0];$('casualties').innerHTML=`${sim.losses[0].toFixed(1)} <small>M</small>`;$('total-casualties').innerHTML=`${(sim.losses[0]+sim.losses[1]).toFixed(1)}<span>M</span>`;$('warheads').textContent=String(sim.missiles.length).padStart(2,'0');$('assessment').textContent=sim.phase>=4?'STABLE':sim.phase===3?'HOSTILITIES':sim.phase===2?'CRITICAL':'CATASTROPHIC';$('midnight').textContent=`${sim.phase} MIN TO MIDNIGHT`;$('doomsday-hand').setAttribute('d',`M40 40L${40-3*sim.phase} ${8+sim.phase}`);
 $('standing-order').textContent=sim.phase>=4?'Establish a defensive perimeter. Protect population centers.':sim.phase>=2?'Engage hostile forces. Preserve strategic launch capability.':'Nuclear weapons authorized. Minimize allied civilian losses.';
 $('escalate').disabled=sim.phase===1||sim.ended||sim.mode==='lab';document.querySelectorAll('.deploy-button').forEach(b=>b.disabled=sim.phase<4||sim.mode==='lab'||sim.ended||sim.budget<TYPES[b.dataset.type].cost);
 $('map-hint').innerHTML=strikeArmed?'☢ NUCLEAR STRIKE ARMED <span>·</span> CLICK TARGET TO LAUNCH':deployType?`PLACE ${TYPES[deployType].name.toUpperCase()} IN WESTERN COMMAND SECTOR`:selectedId?'CLICK MAP TO MOVE <span>·</span> CLICK HOSTILE TO ENGAGE <span>·</span> ESC TO DESELECT':'SELECT A UNIT TO ISSUE ORDERS <span>·</span> SCROLL TO ZOOM <span>·</span> DRAG TO PAN';
 if(eventCount!==sim.events[0]?.id){eventCount=sim.events[0]?.id;$('event-log').innerHTML=sim.events.slice(0,30).map(e=>`<div class="log-entry ${e.kind}"><time>${formatTime(e.time)}</time><span>${e.message}</span></div>`).join('');}
 renderContacts();if(selectedId)renderInspector();else if($('inspector').querySelector('.selected-title'))renderInspector();
 if(sim.ended&&!resultShown){resultShown=true;$('result-title').textContent=sim.mode==='lab'?(sim.winner===null?'Engagement inconclusive.':`${sim.winner===0?'Allied':'Hostile'} force prevails.`):sim.winner===0?'A costly victory.':sim.winner===1?'Command has fallen.':'Nobody won.';$('result-summary').textContent=sim.mode==='lab'?'The engagement has concluded. Review the battlefield or start another experiment.':`After ${formatTime(sim.time)}, the surviving stations fall silent. ${(sim.losses[0]+sim.losses[1]).toFixed(1)} million civilian lives lost. These are the numbers that remain.`;const scores=sim.scores();$('result-stats').innerHTML=[['Allied score',scores[0]],['Hostile score',scores[1]],['Allied units destroyed',sim.kills[1]],['Hostile units destroyed',sim.kills[0]],['Warheads launched',sim.totalNukes],['Allied civilian losses',`${sim.losses[0].toFixed(1)}M`]].map(([name,value])=>`<div class="status-row"><span>${name}</span><strong>${value}</strong></div>`).join('');$('result-dialog').showModal();}
}
const presets={naval:['battleship','submarine'],air:['fighter','fighter'],bombing:['battleship','bomber'],nuclear:['nuclear','nuclear']};
document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{const [a,c]=presets[b.dataset.preset];$('lab-left').value=a;$('lab-right').value=c;document.querySelectorAll('[data-preset]').forEach(v=>v.classList.toggle('active',v===b));updateLabWarning();});
function updateLabWarning(){const a=$('lab-left').value,b=$('lab-right').value;const at=TYPES[a==='nuclear'?'silo':a],bt=TYPES[b==='nuclear'?'silo':b];$('lab-warning').textContent=a==='nuclear'||b==='nuclear'?'Nuclear exchanges auto-launch warheads. Air defenses can intercept incoming missiles.':!at.targets.includes(bt.domain)&&!bt.targets.includes(at.domain)?'Neither force can attack the other. This encounter will end in a standoff after 4 simulation minutes.':!at.targets.includes(bt.domain)||!bt.targets.includes(at.domain)?'Asymmetric encounter: one side cannot return fire against this target type.':'Both sides can engage. All weapons are authorized.';}
$('lab-left').onchange=updateLabWarning;$('lab-right').onchange=updateLabWarning;$('lab-count').oninput=()=>{$('lab-count-value').textContent=$('lab-count').value;};$('launch-lab').onclick=()=>{resumeAfterModal=false;closeDialog('lab-dialog');configureSimulation({mode:'lab',left:$('lab-left').value,right:$('lab-right').value,count:+$('lab-count').value});begin();toast('Battle lab active. Click any contact to inspect combat telemetry.');};
let down=null,dragged=false;
const point=e=>{const r=$('map').getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top};};
$('map').addEventListener('pointerdown',e=>{if(e.button!==0&&e.button!==1)return;const p=point(e);down={...p,px:renderer.pan.x,py:renderer.pan.y};dragged=false;$('map').setPointerCapture(e.pointerId);});
$('map').addEventListener('pointermove',e=>{const p=point(e),geo=renderer.unproject(p.x,p.y);renderer.hover=geo;$('map-coordinates').textContent=`${coordinate(geo.y,'N','S')} / ${coordinate(geo.x,'E','W')}`;if(down&&Math.hypot(p.x-down.x,p.y-down.y)>5)dragged=true;if(down&&dragged){renderer.pan.x=down.px+p.x-down.x;renderer.pan.y=down.py+p.y-down.y;}});
$('map').addEventListener('pointerup',e=>{if(!down)return;const p=point(e);down=null;if(dragged)return;const geo=renderer.unproject(p.x,p.y);if(sim.ended){selectUnit(renderer.pick(sim,p.x,p.y));return;}if(deployType){const r=sim.deploy(deployType,geo.x,geo.y);toast(r.ok?`${TYPES[deployType].name} deployed. ${sim.budget} credits remaining.`:r.reason);updateUI();return;}if(strikeArmed){const r=sim.launch(selectedId,geo.x,geo.y);toast(r.ok?'Nuclear launch confirmed. Missile in flight.':r.reason);if(r.ok)strikeArmed=false;updateUI();return;}const u=renderer.pick(sim,p.x,p.y);const own=selected();if(u){if(u.team===1&&own?.team===0&&!own.dead&&TYPES[own.type].speed){sim.order(own.id,u.x,u.y,u.id);toast('Engagement order acknowledged.');}else selectUnit(u);}else if(own?.team===0&&!own.dead){if(sim.order(own.id,geo.x,geo.y))toast('Movement order acknowledged.');else toast('This installation is stationary.');}else selectUnit(null);updateUI();});
$('map').addEventListener('pointercancel',()=>{down=null;});$('map').addEventListener('wheel',e=>{e.preventDefault();const p=point(e);renderer.changeZoom(e.deltaY<0?1.1:1/1.1,p.x,p.y);},{passive:false});
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();togglePause();}else if(e.key.toLowerCase()==='m')$('sound').click();else if(e.key==='Escape'){selectUnit(null);toast('Order cancelled.');}else if(['1','2','3'].includes(e.key))setSpeed({1:1,2:3,3:10}[e.key]);else if(e.key==='+'||e.key==='=')renderer.changeZoom(1.2);else if(e.key==='-')renderer.changeZoom(1/1.2);else if(e.key.startsWith('Arrow')){e.preventDefault();if(e.key==='ArrowLeft')renderer.pan.x+=45;if(e.key==='ArrowRight')renderer.pan.x-=45;if(e.key==='ArrowUp')renderer.pan.y+=45;if(e.key==='ArrowDown')renderer.pan.y-=45;}});
function frame(now){const dt=Math.min((now-last)/1000,.1);last=now;const advance=dt*speed;const steps=Math.max(1,Math.ceil(advance/.1));for(let i=0;i<steps;i++)sim.tick(advance/steps);renderer.draw(sim,dt);uiClock+=dt;if(uiClock>.2){uiClock=0;updateUI();}requestAnimationFrame(frame);}
configureSimulation();requestAnimationFrame(frame);
// Read-only telemetry for local QA and debugging.
Object.defineProperty(window,'blackout',{get:()=>({mode:sim.mode,time:sim.time,phase:sim.phase,running:sim.running,ended:sim.ended,units:sim.units.map(u=>({...u,trail:undefined})),losses:[...sim.losses],kills:[...sim.kills],missiles:sim.missiles.map(m=>({...m})),events:sim.events.slice(0,8),selectedId,mapLoaded:!!renderer.land,audioEnabled:audio.enabled})});
